uv = uv_orig * 2.0 - 1.0; //Center?
uv = -uv; //Needs flipping first
uv.x *= uAspect.x / uAspect.y;
vec3 r = normalize(vec3(uv, -1.0));
vec3 c = vec3( 0.0 , 0.0 , 0.0 );
float t = 0.0;
for (float i = 0.0; i < 75.0; i += 1.0)
{
vec3 p = r * t;
p.z -= uTime * 3.0;
// rotation
float angle = t * 0.09;
float s = sin(angle), co = cos(angle);
vec2 px = p.yx; //Transposed to look like original
p.x = px.x*co + px.y*s;
p.y = px.x*s - px.y*co;
// L-wall
float v = 6.0 * q3 - max(p.x, p.y);
// color accumulate
c += (1.0 + cos(i*0.2 + vec3(5.0,0.0,2.0))) / (v + 0.03);
// hit flag
float hit = step(v, 2e - 4.0);
// compute wall normal (branchless)
vec3 cell = p - 2.0 * floor(p/2.0);
vec3 normal = normalize( cell - 1.0 );
// reflect ray if hit
vec3 rNew = reflect(-r, normal);
r = normalize( r*(1.0-hit) + rNew*hit );
// reset or advance t
t = t*(1.0-hit) + 0.0*hit;
t += v * 0.3 * (1.0-hit);
}
ret = vec4( tanh(c / 1000.0), 1.0 );
